import {
  ArrowRight, BarChart3, BrainCircuit, CalendarDays, Check, ChevronDown, ChevronRight,
  Circle, CircleHelp, Compass, Flame, FolderKanban, Goal as GoalIcon, HeartPulse, Home,
  Inbox, ListTodo, LogOut, Menu, MessageCircle, Plus, RotateCcw, Settings, ShieldCheck,
  Sparkles, Target, TrendingUp, UserRound, Wind, Zap,
} from 'lucide-react';
import {
  getGetDashboardQueryKey, getGetBriefingQueryKey, getGetHabitQueryKey, getListHabitsQueryKey,
  getListTodosQueryKey, getListRecommendationsQueryKey,
  useAcceptRecommendation, useCompleteOnboarding, useCreateCheckin, useCreateDiagnosis,
  useCreateDomain, useCreateGoal, useCreateHabit, useCreateTodo, useGetBriefing,
  useGetDashboard, useGetCurrentUser, useGetDomainStats, useGetGoal, useGetHabit,
  useGetHeatmap, useGetHabitLeaderboard, useGetProfile, useGetStatsOverview, useGetStatsTrend,
  useListDomains, useListGoals, useListHabits, useListRecommendations, useListTodos, useLogin,
  useLogout, useRegister, useSaveMood, useDismissRecommendation, useUpdateHabit, useUpdateProfile,
  useUpdateTodo,
} from '@workspace/api-client-react';
