  return <PageFrame><PageHeader eyebrow="The direction behind the day" title="Goals" description="Give your consistency somewhere meaningful to go." action={<Button onClick={() => setShowForm((v) => !v)} testId="button-new-goal"><Plus className="h-4 w-4" /> New goal</Button>} />{showForm && <form onSubmit={add} className="mb-6 grid gap-3 rounded-[26px] border border-[hsl(var(--primary)/.3)] bg-[hsl(var(--primary)/.05)] p-5 sm:grid-cols-[1fr_220px_auto] sm:items-end"><Field label="What are you moving toward?" value={title} onChange={setTitle} placeholder="Build a calmer morning" testId="input-goal-title" /><label className="grid gap-1.5 text-sm font-medium">Domain<select value={domainId || domains.data?.[0]?.id || ''} onChange={(e) => setDomainId(e.target.value)} data-testid="select-goal-domain" className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] px-3 py-3 outline-none">{domains.data?.map((d) => <option key={d.id} value={d.id}>{d.name}</option>)}</select></label><Button type="submit" disabled={create.isPending} testId="button-save-goal">{create.isPending ? 'Saving…' : 'Save goal'}</Button></form>}<QueryState loading={goals.isLoading} error={goals.error} onRetry={() => goals.refetch()}>{(goals.data || []).length === 0 ? <EmptyState icon={Target} title="Choose a direction" text="A goal is a gentle north star, not another demand." action={<Button onClick={() => setShowForm(true)} testId="button-empty-new-goal"><Plus className="h-4 w-4" /> Name a goal</Button>} /> : <div className="grid gap-4">{goals.data?.map((goal) => <Link href={`/app/goals/${goal.id}`} key={goal.id} data-testid={`card-goal-${goal.id}`} className="group flex flex-col justify-between gap-5 rounded-[26px] border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-6 transition hover:border-[hsl(var(--primary)/.45)] sm:flex-row sm:items-center"><div className="flex items-start gap-4"><span className="grid h-11 w-11 shrink-0 place-items-center rounded-2xl bg-[hsl(var(--accent)/.2)] text-[hsl(var(--foreground))]"><GoalIcon className="h-5 w-5" /></span><div><h2 className="text-lg font-semibold">{goal.title}</h2><p className="mt-1 text-sm text-[hsl(var(--muted-foreground))]">{goal.description || 'A direction worth returning to.'}</p></div></div><div className="flex items-center gap-5 text-xs text-[hsl(var(--muted-foreground))]"><span>{goal.habitCount} habits</span><span>{goal.openTodoCount} open tasks</span><ChevronRight className="h-5 w-5 transition group-hover:translate-x-1" /></div></Link>)}</div>}</QueryState></PageFrame>;
