function GoalDetail() {
  const { id = '' } = useParams<{ id: string }>(); const goal = useGetGoal(id);
  if (goal.isLoading) return <PageFrame><SkeletonPage /></PageFrame>;
  if (goal.error || !goal.data) return <PageFrame><QueryState error={goal.error} onRetry={() => goal.refetch()}>{null}</QueryState></PageFrame>;
  const g = goal.data;
  return <PageFrame><Link href="/app/goals" className="mb-6 inline-flex items-center gap-1 text-sm font-semibold text-[hsl(var(--muted-foreground))]" data-testid="link-back-goals">← All goals</Link><PageHeader eyebrow="A direction worth returning to" title={g.title} description={g.description || 'Progress is allowed to be quiet.'} /><div className="grid gap-5 lg:grid-cols-2"><section className="rounded-[28px] border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-6"><div className="mb-5 flex items-center justify-between"><h2 className="serif text-2xl">Supporting habits</h2><span className="mono text-xs">{g.habits.length}</span></div>{g.habits.length ? <div className="grid gap-2">{g.habits.map((h) => <Link href={`/app/habits/${h.id}`} key={h.id} className="flex items-center gap-3 rounded-xl p-3 hover:bg-[hsl(var(--muted))]" data-testid={`link-goal-habit-${h.id}`}><span className="grid h-8 w-8 place-items-center rounded-full bg-[hsl(var(--secondary))]"><Zap className="h-4 w-4 text-[hsl(var(--primary))]" /></span><span className="text-sm font-semibold">{h.title}</span><ChevronRight className="ml-auto h-4 w-4 text-[hsl(var(--muted-foreground))]" /></Link>)}</div> : <EmptyState icon={Zap} title="No habits yet" text="Attach a repeatable practice to make this goal tangible." />}</section><section className="rounded-[28px] border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-6"><div className="mb-5 flex items-center justify-between"><h2 className="serif text-2xl">Open tasks</h2><span className="mono text-xs">{g.todos.length}</span></div>{g.todos.length ? <div className="grid gap-2">{g.todos.map((t) => <TodoRow key={t.id} todo={t} onCheck={() => undefined} />)}</div> : <EmptyState icon={ListTodo} title="No tasks attached" text="When the next step is clear, follow-through gets easier." />}</section></div></PageFrame>;
}

function Consistency() {
  const overview = useGetStatsOverview(); const trend = useGetStatsTrend({ days: 30 }); const domains = useGetDomainStats(); const leaderboard = useGetHabitLeaderboard(); const heatmap = useGetHeatmap();
  const trendPoints = trend.data || []; const max = Math.max(...trendPoints.map((p) => p.rate || 0), 1);
  return <PageFrame><PageHeader eyebrow="Patterns, not grades" title="Consistency" description="A compassionate look at what is becoming more natural." /><QueryState loading={overview.isLoading || trend.isLoading} error={overview.error || trend.error} onRetry={() => { overview.refetch(); trend.refetch(); }}>{<><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{[{label: 'Consistency score', value: overview.data?.score == null ? '—' : `${Math.round(overview.data.score)}`, icon: TrendingUp}, {label: 'Current streak', value: overview.data?.currentStreak ?? 0, icon: Flame}, {label: 'Best streak', value: overview.data?.longestStreak ?? 0, icon: Target}, {label: 'Volatility', value: overview.data?.volatility == null ? '—' : `${Math.round(overview.data.volatility)}%`, icon: Wind}].map((item) => <div key={item.label} className="rounded-[24px] border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5"><item.icon className="h-5 w-5 text-[hsl(var(--primary))]" /><p className="mt-5 text-3xl font-semibold">{item.value}</p><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">{item.label}</p></div>)}</div><div className="mt-5 grid gap-5 lg:grid-cols-[1.3fr_.7fr]"><section className="rounded-[28px] border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-6"><div className="flex items-start justify-between"><div><h2 className="serif text-2xl">The last 30 days</h2><p className="mt-1 text-sm text-[hsl(var(--muted-foreground))]">Your follow-through, in a softer shape.</p></div><BarChart3 className="h-5 w-5 text-[hsl(var(--primary))]" /></div><div className="mt-8 flex h-48 items-end gap-1.5">{trendPoints.length ? trendPoints.map((point) => <div key={point.date} title={`${point.date}: ${point.rate ?? 0}%`} data-testid={`bar-trend-${point.date}`} className="group relative flex-1 rounded-t-md bg-[hsl(var(--primary)/.2)] transition hover:bg-[hsl(var(--primary))]" style={{ height: `${Math.max(7, ((point.rate || 0) / max) * 100)}%` }} />) : <EmptyState icon={BarChart3} title="Your chart is taking shape" text="Check in a few times and your pattern will appear." />}</div></section><section className="rounded-[28px] border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-6"><h2 className="serif text-2xl">By domain</h2><div className="mt-6 grid gap-4">{(domains.data || []).length ? domains.data?.map((d) => <div key={d.domainId}><div className="mb-1.5 flex justify-between text-sm"><span>{d.name}</span><span className="mono text-xs">{Math.round(d.rate30d)}%</span></div><div className="h-2 rounded-full bg-[hsl(var(--muted))]"><div className="h-full rounded-full bg-[hsl(var(--primary))]" style={{ width: `${d.rate30d}%` }} /></div></div>) : <p className="text-sm text-[hsl(var(--muted-foreground))]">Domain patterns will appear with more data.</p>}</div></section></div><section className="mt-5 rounded-[28px] border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-6"><div className="flex items-center justify-between"><div><h2 className="serif text-2xl">Habit field</h2><p className="mt-1 text-sm text-[hsl(var(--muted-foreground))]">Every square is a day you kept showing up.</p></div><span className="mono text-[10px] text-[hsl(var(--muted-foreground))]">90 DAYS</span></div><div className="mt-6 grid grid-flow-col grid-rows-7 gap-1 overflow-x-auto">{(heatmap.data || []).slice(-98).map((cell) => <div key={cell.date} title={cell.date} data-testid={`cell-consistency-${cell.date}`} className={cx('h-3 w-3 rounded-[3px]', !cell.rate ? 'bg-[hsl(var(--muted))]' : cell.rate >= 1 ? 'bg-[hsl(var(--primary))]' : 'bg-[hsl(var(--primary)/.35)]')} />)}</div></section><section className="mt-5 rounded-[28px] border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-6"><h2 className="serif text-2xl">Quiet leaders</h2><div className="mt-4 grid gap-2">{(leaderboard.data || []).slice(0, 5).map((row) => <div key={row.habitId} className="flex items-center gap-3 rounded-2xl bg-[hsl(var(--background))] p-3" data-testid={`row-leaderboard-${row.habitId}`}><span className="grid h-8 w-8 place-items-center rounded-full bg-[hsl(var(--accent)/.22)] text-xs font-bold">{row.currentStreak}</span><span className="flex-1 text-sm font-semibold">{row.habitTitle}</span><span className="mono text-xs text-[hsl(var(--muted-foreground))]">{row.rate30d ?? 0}%</span></div>)}{!leaderboard.data?.length && <p className="text-sm text-[hsl(var(--muted-foreground))]">Your most dependable practices will gather here.</p>}</div></section></>}</QueryState></PageFrame>;
}

function Coach() {
  const briefing = useGetBriefing(); const recommendations = useListRecommendations(); const diagnose = useCreateDiagnosis(); const accept = useAcceptRecommendation(); const dismiss = useDismissRecommendation(); const qc = useQueryClient(); const [message, setMessage] = useState('');
  const runDiagnosis = () => diagnose.mutate(undefined, { onSuccess: () => qc.invalidateQueries({ queryKey: getGetBriefingQueryKey() }) });
  return <PageFrame><PageHeader eyebrow="A second perspective" title="Coach" description="Use insight to make the next step lighter, not heavier." action={<Button onClick={runDiagnosis} disabled={diagnose.isPending} testId="button-run-diagnosis"><BrainCircuit className="h-4 w-4" /> {diagnose.isPending ? 'Thinking…' : 'Refresh diagnosis'}</Button>} /><div className="grid gap-5 lg:grid-cols-[1fr_360px]"><div className="grid gap-5"><section className="rounded-[30px] bg-[hsl(var(--primary))] p-7 text-[hsl(var(--primary-foreground))]"><div className="flex items-center gap-2 text-[hsl(var(--primary-foreground)/.7)]"><Sparkles className="h-4 w-4" /><span className="mono text-[10px] uppercase tracking-[.16em]">Today’s briefing</span></div>{briefing.isLoading ? <div className="mt-6 h-24 animate-pulse rounded-2xl bg-[hsl(var(--primary-foreground)/.12)]" /> : <><h2 className="serif mt-6 max-w-2xl text-3xl leading-tight">{briefing.data?.headline || 'Make the next right thing obvious.'}</h2><p className="mt-4 max-w-2xl text-sm leading-7 text-[hsl(var(--primary-foreground)/.75)]">{briefing.data?.body || 'There is no need to solve the whole week today. Pick the smallest action that keeps your north star warm.'}</p><div className="mt-7 grid gap-2">{(briefing.data?.actions || []).map((a, i) => <div key={a} className="flex items-center gap-3 text-sm"><span className="grid h-6 w-6 place-items-center rounded-full bg-[hsl(var(--accent))] text-xs font-bold text-[hsl(var(--foreground))]">{i + 1}</span>{a}</div>)}</div></>}</section><section className="rounded-[28px] border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-6"><div className="mb-4 flex items-center justify-between"><h2 className="serif text-2xl">Suggestions for your week</h2><MessageCircle className="h-5 w-5 text-[hsl(var(--primary))]" /></div>{recommendations.isLoading ? <SkeletonPage /> : recommendations.data?.length ? <div className="grid gap-3">{recommendations.data.map((rec) => <div key={rec.id} className="rounded-2xl border border-[hsl(var(--border))] p-4" data-testid={`card-recommendation-${rec.id}`}><div className="flex items-start gap-3"><span className="mt-0.5 rounded-lg bg-[hsl(var(--secondary))] p-2"><Zap className="h-4 w-4 text-[hsl(var(--primary))]" /></span><div className="min-w-0 flex-1"><h3 className="font-semibold">{rec.title}</h3><p className="mt-1 text-sm leading-6 text-[hsl(var(--muted-foreground))]">{rec.rationale}</p><div className="mt-3 flex gap-2">{rec.status === 'open' && <><Button onClick={() => accept.mutate({ id: rec.id }, { onSuccess: () => qc.invalidateQueries({ queryKey: getListRecommendationsQueryKey() }) })} disabled={accept.isPending} testId={`button-accept-${rec.id}`}>Try this</Button><Button variant="quiet" onClick={() => dismiss.mutate({ id: rec.id }, { onSuccess: () => qc.invalidateQueries({ queryKey: getListRecommendationsQueryKey() }) })} testId={`button-dismiss-${rec.id}`}>Not now</Button></>}</div></div></div></div>)}</div> : <EmptyState icon={Sparkles} title="No suggestions yet" text="Keep living your routine. The useful patterns will surface." />}</section></div><aside className="rounded-[28px] border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-6"><h2 className="serif text-2xl">Ask a small question</h2><p className="mt-2 text-sm leading-6 text-[hsl(var(--muted-foreground))]">Chat is a place to think out loud. For now, leave a prompt for your next check-in.</p><textarea value={message} onChange={(e) => setMessage(e.target.value)} placeholder="What keeps getting in the way?" data-testid="textarea-coach-question" className="mt-6 min-h-[130px] w-full resize-none rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--background))] p-4 text-sm outline-none focus:border-[hsl(var(--primary))]" /><Button className="mt-3 w-full" onClick={() => setMessage('Saved for your next reflection.')} disabled={!message.trim()} testId="button-save-coach-question">Save reflection</Button></aside></div></PageFrame>;
}

function Reviews() {
  const [active, setActive] = useState<'week' | 'month'>('week'); const overview = useGetStatsOverview(); const trend = useGetStatsTrend({ days: active === 'week' ? 30 : 90 }); const [note, setNote] = useState('');
  return <PageFrame><PageHeader eyebrow="Look back with care" title="Reviews" description="Notice what supported you, what drained you, and what deserves a gentler plan." /><div className="mx-auto max-w-3xl"><div className="mb-5 flex rounded-full bg-[hsl(var(--muted))] p-1"><button onClick={() => setActive('week')} data-testid="button-review-week" className={cx('flex-1 rounded-full py-2 text-sm font-semibold', active === 'week' && 'bg-[hsl(var(--card))] shadow-sm')}>This month</button><button onClick={() => setActive('month')} data-testid="button-review-month" className={cx('flex-1 rounded-full py-2 text-sm font-semibold', active === 'month' && 'bg-[hsl(var(--card))] shadow-sm')}>Last 90 days</button></div><section className="rounded-[30px] border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-7"><div className="flex items-center gap-5"><ProgressRing value={overview.data?.rate30d || 0} size={100} /><div><p className="mono text-[10px] uppercase tracking-[.16em] text-[hsl(var(--primary))]">A useful snapshot</p><h2 className="serif mt-2 text-2xl">{(overview.data?.rate30d || 0) > 70 ? 'You are finding your rhythm.' : 'You are still learning your rhythm.'}</h2><p className="mt-1 text-sm text-[hsl(var(--muted-foreground))]">{overview.data?.completedToday || 0} completed today · {overview.data?.currentStreak || 0} day current streak</p></div></div><div className="mt-8 border-t border-[hsl(var(--border))] pt-6"><p className="font-semibold">What do you want to remember?</p><textarea value={note} onChange={(e) => setNote(e.target.value)} placeholder="A win, a friction point, or a small truth…" data-testid="textarea-review-note" className="mt-3 min-h-[120px] w-full resize-none rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--background))] p-4 text-sm outline-none focus:border-[hsl(var(--primary))]" /><Button className="mt-3" onClick={() => setNote('')} disabled={!note.trim()} testId="button-save-review">Save review</Button></div></section><section className="mt-5 rounded-[30px] border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-7"><h2 className="serif text-2xl">The shape of showing up</h2><div className="mt-6 flex h-36 items-end gap-1">{(trend.data || []).map((p) => <div key={p.date} title={p.date} className="flex-1 rounded-t bg-[hsl(var(--accent)/.55)]" style={{ height: `${Math.max(8, p.rate || 0)}%` }} />)}</div></section></div></PageFrame>;
}

function SettingsPage() {
  const profile = useGetProfile(); const update = useUpdateProfile(); const createDomain = useCreateDomain(); const logout = useLogout(); const [name, setName] = useState(''); const [tone, setTone] = useState('encouraging'); const [domainName, setDomainName] = useState('');
  const currentName = name || profile.data?.displayName || '';
  const save = () => update.mutate({ data: { displayName: currentName, coachingTone: tone as 'encouraging' | 'direct' | 'analytical' } }, { onSuccess: () => profile.refetch() });
  const addDomain = () => { if (!domainName.trim()) return; createDomain.mutate({ data: { name: domainName.trim(), icon: 'dot', hue: '#4d927d' } }, { onSuccess: () => setDomainName('') }); };
  return <PageFrame><PageHeader eyebrow="Make it yours" title="Settings" description="The right system feels like a familiar room." /><div className="grid gap-5 lg:grid-cols-[1fr_320px]"><div className="grid gap-5"><section className="rounded-[28px] border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-6 sm:p-7"><div className="flex items-center gap-3"><span className="grid h-11 w-11 place-items-center rounded-full bg-[hsl(var(--secondary))]"><UserRound className="h-5 w-5 text-[hsl(var(--primary))]" /></span><div><h2 className="serif text-2xl">Your profile</h2><p className="text-sm text-[hsl(var(--muted-foreground))]">A few settings for a better fit.</p></div></div><div className="mt-7 grid gap-4 sm:grid-cols-2"><Field label="Display name" value={currentName} onChange={setName} placeholder="Your name" testId="input-profile-name" /><label className="grid gap-1.5 text-sm font-medium">Coach tone<select value={tone} onChange={(e) => setTone(e.target.value)} data-testid="select-coach-tone" className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--background))] px-4 py-3 outline-none"><option value="encouraging">Encouraging</option><option value="direct">Direct</option><option value="analytical">Analytical</option></select></label></div><Button className="mt-5" onClick={save} disabled={update.isPending} testId="button-save-profile">{update.isPending ? 'Saving…' : 'Save changes'}</Button></section><section className="rounded-[28px] border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-6 sm:p-7"><h2 className="serif text-2xl">Your domains</h2><p className="mt-1 text-sm text-[hsl(var(--muted-foreground))]">Name the rooms your attention lives in.</p><div className="mt-5 flex gap-2"><input value={domainName} onChange={(e) => setDomainName(e.target.value)} placeholder="Add a domain" data-testid="input-domain-name" className="min-w-0 flex-1 rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--background))] px-4 py-3 text-sm outline-none focus:border-[hsl(var(--primary))]" /><Button onClick={addDomain} disabled={createDomain.isPending} testId="button-add-domain"><Plus className="h-4 w-4" /> Add</Button></div></section></div><aside className="grid content-start gap-5"><div className="rounded-[28px] bg-[hsl(var(--secondary))] p-6"><ShieldCheck className="h-5 w-5 text-[hsl(var(--primary))]" /><h2 className="serif mt-5 text-2xl">Private by default</h2><p className="mt-2 text-sm leading-6 text-[hsl(var(--foreground)/.68)]">ASTALY is a place for your honest patterns. Your pace belongs to you.</p></div><button onClick={() => logout.mutate(undefined, { onSuccess: () => { window.location.href = '/'; } })} data-testid="button-settings-logout" className="flex items-center justify-center gap-2 rounded-2xl border border-[hsl(var(--border))] px-4 py-3 text-sm font-semibold hover:bg-[hsl(var(--muted))]"><LogOut className="h-4 w-4" /> Sign out</button></aside></div></PageFrame>;
}

function AuthLayout({ children, title, eyebrow }: { children: ReactNode; title: string; eyebrow: string }) {
  return <div className="grain grid min-h-[100dvh] bg-[hsl(var(--background))] lg:grid-cols-[.85fr_1.15fr]"><div className="relative hidden overflow-hidden bg-[hsl(var(--sidebar))] p-10 lg:block"><Logo light /><div className="absolute bottom-16 left-10 right-10"><p className="mono text-[10px] uppercase tracking-[.18em] text-[hsl(var(--sidebar-primary))]">A steady place to land</p><h2 className="serif mt-4 max-w-md text-5xl leading-[1.03] text-[hsl(var(--sidebar-foreground))]">Follow through, without becoming someone else.</h2><div className="mt-9 h-1 w-20 rounded-full bg-[hsl(var(--sidebar-primary))]" /></div><div className="absolute -right-28 top-32 h-64 w-64 rounded-full border-[30px] border-[hsl(var(--sidebar-primary)/.18)]" /></div><div className="flex flex-col p-6 sm:p-10"><div className="lg:hidden"><Logo /></div><div className="m-auto w-full max-w-[420px] py-12"><p className="mono text-[10px] uppercase tracking-[.18em] text-[hsl(var(--primary))]">{eyebrow}</p><h1 className="serif mt-3 text-4xl tracking-[-.04em]">{title}</h1>{children}</div></div></div>;
}
function Login() {
  const login = useLogin(); const [, setLocation] = useLocation(); const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [error, setError] = useState('');
  const submit = (e: React.FormEvent) => { e.preventDefault(); setError(''); login.mutate({ data: { email, password } }, { onSuccess: (u) => setLocation(u.onboardingCompleted ? '/app' : '/onboarding'), onError: () => setError('That email and password did not match.') }); };
  return <AuthLayout title="Welcome back." eyebrow="Return to your rhythm"><form onSubmit={submit} className="mt-8 grid gap-4"><Field label="Email" value={email} onChange={setEmail} type="email" placeholder="you@example.com" testId="input-login-email" /><Field label="Password" value={password} onChange={setPassword} type="password" placeholder="At least 8 characters" testId="input-login-password" />{error && <p className="rounded-xl bg-[hsl(var(--destructive)/.08)] p-3 text-sm text-[hsl(var(--destructive))]" data-testid="status-login-error">{error}</p>}<Button type="submit" className="mt-2 w-full py-3" disabled={login.isPending} testId="button-login-submit">{login.isPending ? 'Opening…' : 'Open ASTALY'} <ArrowRight className="h-4 w-4" /></Button><p className="text-center text-sm text-[hsl(var(--muted-foreground))]">New here? <Link href="/register" className="font-semibold text-[hsl(var(--primary))]" data-testid="link-register">Create an account</Link></p></form></AuthLayout>;
}
function Register() {
  const register = useRegister(); const [, setLocation] = useLocation(); const [form, setForm] = useState({ name: '', email: '', password: '', confirm: '' }); const [error, setError] = useState('');
  const set = (key: keyof typeof form) => (value: string) => setForm((f) => ({ ...f, [key]: value }));
  const submit = (e: React.FormEvent) => { e.preventDefault(); if (form.password !== form.confirm) { setError('Passwords need to match.'); return; } register.mutate({ data: { displayName: form.name, email: form.email, password: form.password, confirmPassword: form.confirm } }, { onSuccess: () => setLocation('/onboarding'), onError: () => setError('We could not create that account yet.') }); };
  return <AuthLayout title="Make space for follow-through." eyebrow="Start with one honest step"><form onSubmit={submit} className="mt-8 grid gap-4"><Field label="Your name" value={form.name} onChange={set('name')} placeholder="What should we call you?" testId="input-register-name" /><Field label="Email" value={form.email} onChange={set('email')} type="email" placeholder="you@example.com" testId="input-register-email" /><Field label="Password" value={form.password} onChange={set('password')} type="password" placeholder="At least 8 characters" testId="input-register-password" /><Field label="Confirm password" value={form.confirm} onChange={set('confirm')} type="password" placeholder="One more time" testId="input-register-confirm" />{error && <p className="rounded-xl bg-[hsl(var(--destructive)/.08)] p-3 text-sm text-[hsl(var(--destructive))]" data-testid="status-register-error">{error}</p>}<Button type="submit" className="mt-2 w-full py-3" disabled={register.isPending} testId="button-register-submit">{register.isPending ? 'Making room…' : 'Create my space'} <ArrowRight className="h-4 w-4" /></Button><p className="text-center text-sm text-[hsl(var(--muted-foreground))]">Already have an account? <Link href="/login" className="font-semibold text-[hsl(var(--primary))]" data-testid="link-login">Sign in</Link></p></form></AuthLayout>;
}

function Onboarding() {
  const domains = useListDomains(); const complete = useCompleteOnboarding(); const [, setLocation] = useLocation(); const [step, setStep] = useState(0); const [name, setName] = useState(''); const [selected, setSelected] = useState<string[]>([]); const [northStar, setNorthStar] = useState(''); const [tone, setTone] = useState<'encouraging' | 'direct' | 'analytical'>('encouraging'); const [killer, setKiller] = useState('');
  const domainList = domains.data || []; const toggle = (key: string) => setSelected((items) => items.includes(key) ? items.filter((i) => i !== key) : items.length < 4 ? [...items, key] : items);
  const finish = () => complete.mutate({ data: { displayName: name, timezone: Intl.DateTimeFormat().resolvedOptions().timeZone, primaryDomainKeys: selected, minutesWeekday: 30, minutesWeekend: 60, wakeTime: '07:00', sleepTime: '23:00', consistencyKiller: killer, coachingTone: tone, northStar } }, { onSuccess: () => setLocation('/app') });
  const steps = [{ title: 'What should we call you?', text: 'ASTALY is yours. Start with your name.', body: <Field label="Your name" value={name} onChange={setName} placeholder="A name that feels like you" testId="input-onboarding-name" /> }, { title: 'Where does your attention go?', text: 'Choose two to four rooms for your energy.', body: <div className="grid gap-2">{domainList.map((d) => <button type="button" key={d.key} onClick={() => toggle(d.key)} data-testid={`button-domain-${d.key}`} className={cx('flex items-center gap-3 rounded-2xl border p-4 text-left transition', selected.includes(d.key) ? 'border-[hsl(var(--primary))] bg-[hsl(var(--primary)/.08)]' : 'border-[hsl(var(--border))] hover:border-[hsl(var(--primary)/.4)]')}><span className="grid h-9 w-9 place-items-center rounded-xl bg-[hsl(var(--secondary))] text-[hsl(var(--primary))]">{selected.includes(d.key) ? <Check className="h-4 w-4" /> : <FolderKanban className="h-4 w-4" />}</span><span><b className="block text-sm">{d.name}</b><small className="text-xs text-[hsl(var(--muted-foreground))]">{d.description}</small></span></button>)}</div> }, { title: 'What are you moving toward?', text: 'A north star makes the little steps feel connected.', body: <><Field label="Your north star" value={northStar} onChange={setNorthStar} placeholder="I want my days to feel…" testId="input-onboarding-north-star" /><label className="mt-4 grid gap-1.5 text-sm font-medium">When plans wobble, what usually gets in the way?<textarea value={killer} onChange={(e) => setKiller(e.target.value)} placeholder="Be kind and specific." data-testid="textarea-onboarding-killer" className="min-h-[100px] rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-4 text-sm outline-none focus:border-[hsl(var(--primary))]" /></label></> }, { title: 'How should ASTALY sound?', text: 'You can change this anytime.', body: <div className="grid gap-3">{[['encouraging', 'Warm and steady', 'A little lift when you need it.'], ['direct', 'Clear and direct', 'Short, honest, no fuss.'], ['analytical', 'Thoughtful and analytical', 'Patterns first, advice second.']].map(([key, label, copy]) => <button type="button" key={key} onClick={() => setTone(key as typeof tone)} data-testid={`button-tone-${key}`} className={cx('rounded-2xl border p-4 text-left', tone === key ? 'border-[hsl(var(--primary))] bg-[hsl(var(--primary)/.08)]' : 'border-[hsl(var(--border))]')}><b className="block text-sm">{label}</b><span className="text-xs text-[hsl(var(--muted-foreground))]">{copy}</span></button>)}</div> }];
  const current = steps[step]; const canContinue = step === 0 ? name.trim().length > 0 : step === 1 ? selected.length >= 2 : step === 2 ? northStar.trim().length > 0 : true;
  return <div className="grain flex min-h-[100dvh] flex-col bg-[hsl(var(--background))]"><header className="flex items-center justify-between px-6 py-5 sm:px-10"><Logo /><span className="mono text-[10px] uppercase tracking-[.16em] text-[hsl(var(--muted-foreground))]">Step {step + 1} of {steps.length}</span></header><main className="mx-auto flex w-full max-w-[620px] flex-1 flex-col justify-center px-6 py-10"><div className="mb-9 flex gap-2">{steps.map((_, i) => <div key={i} className={cx('h-1.5 flex-1 rounded-full', i <= step ? 'bg-[hsl(var(--primary))]' : 'bg-[hsl(var(--muted))]')} />)}</div><p className="mono text-[10px] uppercase tracking-[.16em] text-[hsl(var(--primary))]">A small beginning</p><h1 className="serif mt-3 text-4xl tracking-[-.04em] sm:text-5xl">{current.title}</h1><p className="mt-3 text-[hsl(var(--muted-foreground))]">{current.text}</p><div className="mt-9">{current.body}</div><div className="mt-9 flex items-center justify-between"><button onClick={() => setStep((s) => Math.max(0, s - 1))} disabled={step === 0} data-testid="button-onboarding-back" className="text-sm font-semibold text-[hsl(var(--muted-foreground))] disabled:opacity-0">Back</button>{step < steps.length - 1 ? <Button onClick={() => setStep((s) => s + 1)} disabled={!canContinue} testId="button-onboarding-next">Continue <ArrowRight className="h-4 w-4" /></Button> : <Button onClick={finish} disabled={complete.isPending} testId="button-onboarding-finish">{complete.isPending ? 'Setting up…' : 'Open my ASTALY'} <ArrowRight className="h-4 w-4" /></Button>}</div></main></div>;
}

function Landing() {
  return <div className="grain overflow-hidden bg-[hsl(var(--background))]"><header className="mx-auto flex max-w-7xl items-center justify-between px-6 py-6 lg:px-10"><Logo /><nav className="hidden items-center gap-7 text-sm text-[hsl(var(--muted-foreground))] md:flex"><a href="#how" data-testid="link-how-it-works">How it works</a><a href="#promise" data-testid="link-promise">The promise</a><Link href="/login" data-testid="link-landing-login">Sign in</Link></nav><Link href="/register" className="rounded-full bg-[hsl(var(--primary))] px-4 py-2.5 text-sm font-semibold text-[hsl(var(--primary-foreground))]" data-testid="link-landing-start">Start simply</Link></header><main><section className="relative mx-auto grid max-w-7xl items-center gap-14 px-6 pb-24 pt-14 lg:grid-cols-[1.05fr_.95fr] lg:px-10 lg:pb-36 lg:pt-24"><div className="relative z-10 animate-rise"><p className="mono text-[10px] uppercase tracking-[.2em] text-[hsl(var(--primary))]">A consistency operating system</p><h1 className="serif mt-6 max-w-3xl text-[clamp(3.8rem,8vw,7.8rem)] font-semibold leading-[.91] tracking-[-.065em]">Follow through<br /><em className="font-normal text-[hsl(var(--primary))]">with less force.</em></h1><p className="mt-8 max-w-lg text-lg leading-8 text-[hsl(var(--muted-foreground))]">ASTALY gives your good intentions a place to land: one clear day, a few repeatable practices, and enough perspective to keep going.</p><div className="mt-9 flex flex-wrap items-center gap-3"><Link href="/register" className="inline-flex items-center gap-2 rounded-full bg-[hsl(var(--primary))] px-5 py-3.5 text-sm font-semibold text-[hsl(var(--primary-foreground))]" data-testid="link-hero-start">Build your rhythm <ArrowRight className="h-4 w-4" /></Link><a href="#how" className="inline-flex items-center gap-2 rounded-full px-5 py-3.5 text-sm font-semibold" data-testid="link-hero-learn">See how it feels <ChevronDown className="h-4 w-4" /></a></div><div className="mt-14 flex items-center gap-4 text-xs text-[hsl(var(--muted-foreground))]"><span className="flex -space-x-2"><i className="grid h-8 w-8 place-items-center rounded-full border-2 border-[hsl(var(--background))] bg-[hsl(var(--accent))] not-italic">M</i><i className="grid h-8 w-8 place-items-center rounded-full border-2 border-[hsl(var(--background))] bg-[hsl(var(--chart-3))] not-italic">R</i><i className="grid h-8 w-8 place-items-center rounded-full border-2 border-[hsl(var(--background))] bg-[hsl(var(--chart-4))] not-italic">A</i></span><span>For people who are done starting over.</span></div></div><div className="relative animate-rise delay-2"><div className="absolute -inset-10 rounded-full bg-[hsl(var(--accent)/.13)] blur-3xl" /><div className="relative rotate-[3deg] rounded-[32px] bg-[hsl(var(--sidebar))] p-5 shadow-2xl sm:p-7"><div className="flex items-center justify-between text-[hsl(var(--sidebar-foreground))]"><div><p className="mono text-[9px] uppercase tracking-[.16em] text-[hsl(var(--sidebar-primary))]">Tuesday, October 8</p><p className="serif mt-2 text-2xl">Keep your promises small.</p></div><div className="grid h-12 w-12 place-items-center rounded-full border-4 border-[hsl(var(--sidebar-primary))] text-xs text-[hsl(var(--sidebar-foreground))]">68%</div></div><div className="mt-7 rounded-2xl bg-[hsl(var(--sidebar-accent))] p-4"><p className="text-xs text-[hsl(var(--sidebar-foreground)/.65)]">Today’s rhythm</p>{['Morning pages', 'Walk after lunch', 'Send the proposal'].map((t, i) => <div key={t} className="mt-4 flex items-center gap-3"><span className={cx('grid h-6 w-6 place-items-center rounded-full border', i < 2 ? 'border-[hsl(var(--sidebar-primary))] bg-[hsl(var(--sidebar-primary))] text-[hsl(var(--sidebar-primary-foreground))]' : 'border-[hsl(var(--sidebar-foreground)/.3)]')}>{i < 2 && <Check className="h-3.5 w-3.5" />}</span><span className={cx('text-sm', i < 2 && 'text-[hsl(var(--sidebar-foreground)/.55)] line-through')}>{t}</span></div>)}</div><div className="mt-4 grid grid-cols-2 gap-3"><div className="rounded-2xl bg-[hsl(var(--sidebar-accent))] p-4"><Flame className="h-4 w-4 text-[hsl(var(--sidebar-primary))]" /><p className="mt-4 text-2xl text-[hsl(var(--sidebar-foreground))]">12</p><p className="text-[10px] text-[hsl(var(--sidebar-foreground)/.55)]">day streak</p></div><div className="rounded-2xl bg-[hsl(var(--accent))] p-4 text-[hsl(var(--foreground))]"><Sparkles className="h-4 w-4" /><p className="mt-4 text-sm font-semibold">One thing is enough.</p><p className="mt-2 text-[10px] opacity-60">A note from ASTALY</p></div></div></div><span className="absolute -bottom-8 -left-8 grid h-20 w-20 place-items-center rounded-full border border-[hsl(var(--border))] bg-[hsl(var(--card))] text-[hsl(var(--primary))] shadow-lg"><Wind className="h-7 w-7" /></span></div></section><section id="how" className="border-y border-[hsl(var(--border))] bg-[hsl(var(--secondary)/.45)] px-6 py-24 lg:px-10"><div className="mx-auto max-w-7xl"><p className="mono text-[10px] uppercase tracking-[.2em] text-[hsl(var(--primary))]">A kinder system</p><div className="mt-5 grid gap-12 lg:grid-cols-[.8fr_1.2fr]"><h2 className="serif max-w-xl text-4xl leading-tight tracking-[-.04em] sm:text-5xl">You do not need more motivation. You need a <em className="font-normal text-[hsl(var(--primary))]">visible next step.</em></h2><div className="grid gap-8 sm:grid-cols-3">{[['01', 'See today', 'A calm, honest list that makes room for what matters now.'], ['02', 'Keep showing up', 'Small check-offs turn into evidence you can trust yourself.'], ['03', 'Learn your pattern', 'Reviews and gentle coaching help you adjust without judgment.']].map(([n, t, c]) => <div key={n} className="border-t border-[hsl(var(--border))] pt-4"><span className="mono text-xs text-[hsl(var(--primary))]">{n}</span><h3 className="mt-8 text-lg font-semibold">{t}</h3><p className="mt-2 text-sm leading-6 text-[hsl(var(--muted-foreground))]">{c}</p></div>)}</div></div></div></section><section id="promise" className="mx-auto max-w-7xl px-6 py-24 lg:px-10 lg:py-36"><div className="grid items-end gap-14 lg:grid-cols-[1fr_.8fr]"><div><p className="mono text-[10px] uppercase tracking-[.2em] text-[hsl(var(--primary))]">The ASTALY promise</p><h2 className="serif mt-5 max-w-2xl text-5xl leading-[.98] tracking-[-.05em] sm:text-7xl">A life built in <span className="text-[hsl(var(--primary))]">ordinary</span> days.</h2></div><div><p className="text-lg leading-8 text-[hsl(var(--muted-foreground))]">No streak-shaming. No productivity theater. Just a thoughtfully designed place to notice what you care about and return to it.</p><Link href="/register" className="mt-7 inline-flex items-center gap-2 font-semibold text-[hsl(var(--primary))]" data-testid="link-promise-start">Come in, start small <ArrowRight className="h-4 w-4" /></Link></div></div><div className="mt-20 grid gap-4 sm:grid-cols-3"><div className="rounded-[28px] bg-[hsl(var(--primary))] p-7 text-[hsl(var(--primary-foreground))] sm:col-span-2"><Target className="h-6 w-6 text-[hsl(var(--accent))]" /><p className="serif mt-16 max-w-md text-3xl leading-tight">The goal is not a perfect day. It is a day you can come back to.</p></div><div className="rounded-[28px] bg-[hsl(var(--accent))] p-7"><HeartPulse className="h-6 w-6" /><p className="serif mt-16 text-3xl leading-tight">Make it personal.</p></div></div></section></main><footer className="border-t border-[hsl(var(--border))] px-6 py-8 lg:px-10"><div className="mx-auto flex max-w-7xl flex-col justify-between gap-3 text-sm text-[hsl(var(--muted-foreground))] sm:flex-row"><Logo /><span>For the steady becoming.</span></div></footer></div>;
}

function RoutedErrorBoundary({ children }: { children: ReactNode }) { const [location] = useLocation(); return <ErrorBoundary resetKey={location}>{children}</ErrorBoundary>; }
function Private({ children }: { children: ReactNode }) { return <AppShell>{children}</AppShell>; }
function Router() {
  return <RoutedErrorBoundary><Switch>
    <Route path="/" component={Landing} /><Route path="/login" component={Login} /><Route path="/register" component={Register} /><Route path="/onboarding" component={Onboarding} />
    <Route path="/app" component={() => <Private><Today /></Private>} /><Route path="/app/inbox" component={() => <Private><TodoView view="inbox" title="Inbox" description="Catch everything before it asks to be remembered." /></Private>} /><Route path="/app/upcoming" component={() => <Private><TodoView view="upcoming" title="Upcoming" description="A little visibility for the days ahead." /></Private>} />
    <Route path="/app/habits" component={() => <Private><Habits /></Private>} /><Route path="/app/habits/:id" component={() => <Private><HabitDetail /></Private>} /><Route path="/app/goals" component={() => <Private><Goals /></Private>} /><Route path="/app/goals/:id" component={() => <Private><GoalDetail /></Private>} />
    <Route path="/app/consistency" component={() => <Private><Consistency /></Private>} /><Route path="/app/coach" component={() => <Private><Coach /></Private>} /><Route path="/app/reviews" component={() => <Private><Reviews /></Private>} /><Route path="/app/settings" component={() => <Private><SettingsPage /></Private>} />
    <Route component={NotFound} />
  </Switch></RoutedErrorBoundary>;
}
function App() { return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><Router /></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>; }
export default App;